   152	// codexPromptText reports whether a raw rollout line is a user-prompt
   153	// response_item and returns its concatenated input_text. Assistant messages,
   154	// tool calls, and event_msg lines return false.
   155	func codexPromptText(raw []byte) (string, bool) {
   156		var line struct {
   157			Type    string          `json:"type"`
   158			Payload json.RawMessage `json:"payload"`
   159		}
   160		if err := json.Unmarshal(raw, &line); err != nil || line.Type != "response_item" {
   161			return "", false
   162		}
   163		var payload struct {
   164			Type    string `json:"type"`
   165			Role    string `json:"role"`
   166			Content []struct {
   167				Type string `json:"type"`
   168				Text string `json:"text"`
   169			} `json:"content"`
   170		}
   171		if err := json.Unmarshal(line.Payload, &payload); err != nil {
   172			return "", false
   173		}
   174		if payload.Type != "message" || payload.Role != "user" {
   175			return "", false
   176		}
   177		var texts []string
   178		for _, item := range payload.Content {
   179			if item.Type == "input_text" {
